"""Tests for ``dataplaybook.utils.prettytable``."""import loggingimport pytestfrom dataplaybook.utils.prettytable import StatSummary, pretty_table, table_datadef test_stat_summary_stats_omits_zeros() -> None:    assert StatSummary.stats(added=3, merged=0, total=1) == {"added": 3, "total": 1}    assert StatSummary.stats() == {}def test_stat_summary_add_promotes_stat_cols() -> None:    summary = StatSummary(stat_cols=("added", "merged", "total"))    summary.add(        {"added": 2, "merged": 1, "total": 5, "pending": 3},        source="files",        step="load",        entity="items",    )    assert summary.rows == [        {            "source": "files",            "step": "load",            "entity": "items",            "added": 2,            "merged": 1,            "total": 5,            "detail": "pending=3",        }    ]def test_stat_summary_add_detail_only() -> None:    summary = StatSummary(stat_cols=("added",))    summary.add({}, source="west", step="comments", entity="comments", detail="append")    assert summary.rows == [        {            "source": "west",            "step": "comments",            "entity": "comments",            "detail": "append",        }    ]def test_stat_summary_label_cols_filter_unknown_labels() -> None:    summary = StatSummary(stat_cols=("added",), label_cols=("source", "step", "entity"))    summary.add(        StatSummary.stats(added=1),        source="X",        step="y",        entity="z",        typo="drop-me",    )    assert summary.rows == [        {"source": "X", "step": "y", "entity": "z", "added": 1},    ]def test_stat_summary_logs_unknown_labels(    caplog: pytest.LogCaptureFixture,) -> None:    summary = StatSummary(stat_cols=("added",), label_cols=("source", "step", "entity"))    with caplog.at_level(logging.WARNING):        summary.add(            StatSummary.stats(added=1), source="X", step="y", entity="z", typo="oops"        )    assert "unknown labels: ['typo']" in caplog.text    assert len(summary.warnings) == 1    assert "unknown labels" in summary.warnings[0]def test_stat_summary_logs_missing_labels(    caplog: pytest.LogCaptureFixture,) -> None:    summary = StatSummary(stat_cols=("added",), label_cols=("source", "step", "entity"))    with caplog.at_level(logging.WARNING):        summary.add(StatSummary.stats(added=1), source="X", step="y")    assert "missing labels: ['entity']" in caplog.textdef test_stat_summary_logs_unknown_stats(    caplog: pytest.LogCaptureFixture,) -> None:    summary = StatSummary(stat_cols=("added", "merged"))    with caplog.at_level(logging.WARNING):        summary.add(            {"added": 1, "pending": 2},            source="east",            step="import",            entity="items",        )    assert "unknown stats (→detail): ['pending']" in caplog.textdef test_stat_summary_detail_stats_skip_unknown_warning(    caplog: pytest.LogCaptureFixture,) -> None:    summary = StatSummary(stat_cols=("added",), detail_stats=("pending", "skipped"))    with caplog.at_level(logging.WARNING):        summary.add(            {"added": 7, "skipped": 1},            source="staging",            step="add_ids",            entity="items",        )    assert "unknown stats" not in caplog.text    assert summary.rows[0]["detail"] == "skipped=1"def test_stat_summary_custom_detail_col() -> None:    summary = StatSummary(stat_cols=("added",), detail_col="notes")    summary.add({"added": 1, "extra": 9}, source="X", step="y", entity="z")    assert summary.rows[0]["notes"] == "extra=9"    assert "detail" not in summary.rows[0]def test_stat_summary_print_replays_warnings(    capsys: pytest.CaptureFixture[str],) -> None:    summary = StatSummary(stat_cols=("added",), label_cols=("source", "step", "entity"))    summary.add(        StatSummary.stats(added=1), source="X", step="y", entity="z", typo="oops"    )    summary.print(wrap_length=0)    assert summary.warnings == ["StatSummary unknown labels: ['typo']"]def test_stat_summary_print(capsys: pytest.CaptureFixture[str]) -> None:    summary = StatSummary(stat_cols=("added",), label_cols=("source", "entity"))    summary.add(StatSummary.stats(added=42), source="staging", entity="items")    summary.print(wrap_length=0)    err = capsys.readouterr().err    assert "staging" in err    assert "42" in err    assert "items" in errdef test_table_data_and_pretty_table() -> None:    rows = [{"a": 1, "b": 2}, {"a": 3, "c": 4}]    headers, data = table_data(rows)    assert set(headers) == {"a", "b", "c"}    table = pretty_table(headers, data, wrap_length=0)    assert "1" in str(table)    assert "4" in str(table)